Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Card is not Orc.Cards.Card played || !object.ReferenceEquals(played, view.Host))
    {
        return;
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(played);
    if (runtime is null)
    {
        return;
    }

    var targets = await runtime.SelectAsync(played, new Orc.Game.Effects.EffectSelector("one", "enemy"));
    foreach (var target in targets)
    {
        await runtime.DamageAsync(target, 3, played, ct);
    }

    var owner = (played as Orc.Game.Cards.CardBase)?.Owner;
    var hq = owner?.Hq;
    if (hq is not null)
    {
        await runtime.BuffAsync(hq, 0, 5, Orc.Game.Effects.EffectDuration.Permanent, ct, played);
    }
};
